\title{The Join of Gorenstein Polytopes Is Always Gorenstein}
\author{Aristotle}
\date{2026-06-28}

\begin{document}
\maketitle

\begin{abstract}
We resolve, in the negative, the conjecture that the \emph{join} of two Gorenstein
lattice polytopes can fail to be Gorenstein. Working at the level of the Ehrhart
$\hstar$-polynomial (the $\delta$-polynomial)---the standard faithful invariant governing
the Gorenstein property via the Stanley--Hibi symmetry criterion---we show that the join
corresponds exactly to multiplication of $\hstar$-polynomials, and that the product of two
palindromic polynomials over an integral domain is again palindromic. Consequently the
join of Gorenstein polytopes is \textbf{always} Gorenstein. We package the $\hstar$-data
of a Gorenstein polytope as a structure carrying three invariants---constant term $1$,
coefficientwise nonnegativity, and reverse-symmetry---and prove the join is total on this
class. We further establish degree additivity
($\deg \hstar_{P*Q} = \deg \hstar_P + \deg \hstar_Q$), a point-identity law, and
commutativity and associativity, exhibiting Gorenstein $\hstar$-data as a commutative
monoid under the join. Finally, we explain why the original intuition is sound but
misattributed: it is the \emph{free sum} $P \oplus Q$, whose $\hstar$-polynomial is
governed by a non-multiplicative convolution, that genuinely can break the Gorenstein
property.
\end{abstract}

\section{Introduction}

A \emph{lattice polytope} is the convex hull of finitely many points of the integer
lattice $\Z^d$. Among lattice polytopes the \emph{Gorenstein} ones are characterized by a
hidden symmetry of their lattice-point enumerator; the most symmetric, the
\emph{reflexive} polytopes, classify Gorenstein toric Fano varieties and, via
Batyrev--Borisov, Calabi--Yau hypersurfaces in mirror symmetry.

Two natural ways to combine polytopes are the \emph{join} $P * Q$ (convex hull of $P$ and
$Q$ in skew affine subspaces of a common space) and the \emph{free sum} $P \oplus Q$
(meeting at a shared relative-interior point). The conjecture motivating this work
asserted:
\begin{quote}
\textbf{(Conjecture, refuted.)} There exist Gorenstein lattice polytopes $P, Q$ such that
the join $P * Q$ is not Gorenstein.
\end{quote}
We refute it: the Gorenstein property is always inherited by the join. The genuine
failure occurs for the free sum.

\section{Background and definitions}

\subsection{The Ehrhart series and the $\hstar$-polynomial}

Let $P \subseteq \R^N$ be a $d$-dimensional lattice polytope and
$L_P(t) = \#(tP \cap \Z^N)$. By Ehrhart's theorem $L_P$ is a polynomial of degree $d$, and
\[
\Ehr_P(z) = \sum_{t \ge 0} L_P(t)\, z^t = \frac{\hstar_P(z)}{(1-z)^{d+1}},
\]
with numerator $\hstar_P(z) = \sum_{i=0}^{s} \hstar_i z^i$, the \emph{$\hstar$-polynomial}
(equivalently $\delta$-polynomial). Stanley's theorem gives $\hstar_i \in \Z_{\ge 0}$, and
normalization gives $\hstar_0 = 1$. We write $s = \deg \hstar_P$ for the degree of $P$ and
$d+1-s$ for its codegree.

\subsection{The Gorenstein property}

\begin{definition}[Gorenstein, $\hstar$-form]
A lattice polytope $P$ is \emph{Gorenstein} if its $\hstar$-vector is palindromic:
$\hstar_i = \hstar_{s-i}$ for all $0 \le i \le s$, where $s = \deg \hstar_P$. Equivalently
$\rev(\hstar_P) = \hstar_P$, where $\rev$ reverses the coefficient list. This is the
Stanley--Hibi criterion.
\end{definition}

\begin{definition}[Gorenstein $\hstar$-data, \texttt{GorensteinHStar}]
A \emph{Gorenstein $\hstar$-datum} is a polynomial $h \in \Z[z]$ with
(1) $h(0) = 1$, (2) every coefficient $\ge 0$, and (3) $\rev(h) = h$.
\end{definition}

\subsection{The join and its Ehrhart multiplicativity}

\begin{definition}[Join]
For $P \subseteq \R^m$, $Q \subseteq \R^n$,
\[
P * Q = \conv\big( (P \times \{0\} \times \{0\}) \cup (\{0\} \times Q \times \{1\}) \big)
\subseteq \R^{m+n+1},
\]
with $\dim(P * Q) = \dim P + \dim Q + 1$.
\end{definition}

\begin{theorem}[Classical join multiplicativity]
$\hstar_{P * Q}(z) = \hstar_P(z) \cdot \hstar_Q(z)$. Equivalently, codegrees add and the
degrees of the $\hstar$-polynomials add. We adopt this as the model of the join on
$\hstar$-data: the join multiplies polynomials.
\end{theorem}

\section{Main results}

\subsection{The join is total on Gorenstein $\hstar$-data}

\begin{definition}[Join of $\hstar$-data, \texttt{GorensteinHStar.join}]
For Gorenstein $\hstar$-data $P, Q$, let $P.\mathtt{join}\,Q$ be the datum with polynomial
$P.h \cdot Q.h$.
\end{definition}

\begin{theorem}[Closure under join]\label{thm:closure}
If $P, Q$ are Gorenstein $\hstar$-data, so is $P.\mathtt{join}\,Q$:
\begin{itemize}
\item \emph{(\texttt{join\_coeff\_zero}.)} $(P.h \cdot Q.h)(0) = 1 \cdot 1 = 1$.
\item \emph{(\texttt{join\_nonneg}.)} $[z^i](P.h \cdot Q.h) = \sum_{j+k=i} [z^j]P.h \cdot
[z^k]Q.h \ge 0$.
\item \emph{(\texttt{join\_symm}.)} $\rev(P.h \cdot Q.h) = \rev(P.h)\cdot\rev(Q.h) =
P.h\cdot Q.h$.
\end{itemize}
\end{theorem}

\begin{proof}[Proof sketch]
Constant term and nonnegativity follow from the convolution formula for the coefficients
of a product. For symmetry, reversal is multiplicative over an integral domain:
$\rev(p \cdot q) = \rev(p)\cdot\rev(q)$ in $\Z[z]$ (no leading-coefficient cancellation).
Substituting $\rev(P.h)=P.h$, $\rev(Q.h)=Q.h$ gives $\rev(P.h\cdot Q.h)=P.h\cdot Q.h$.
Equivalently, if $p$ of degree $d$ satisfies $z^d p(1/z) = p(z)$ and likewise $q$ of
degree $e$, then $z^{d+e}(pq)(1/z) = (z^d p(1/z))(z^e q(1/z)) = p(z)q(z)$.
\end{proof}

\begin{corollary}[Refutation of the conjecture]
No Gorenstein polytopes have a non-Gorenstein join; \texttt{join\_symm} holds for all
$P,Q$: $\rev\big((P.\mathtt{join}\,Q).h\big) = (P.\mathtt{join}\,Q).h$.
\end{corollary}

\subsection{Multiplicativity, nonvanishing, degree}

\begin{proposition}[\texttt{join\_h}]
$(P.\mathtt{join}\,Q).h = P.h \cdot Q.h$, the formal record of
$\hstar_{P*Q} = \hstar_P \cdot \hstar_Q$.
\end{proposition}

\begin{lemma}[\texttt{h\_ne\_zero}]
Every Gorenstein $\hstar$-polynomial is nonzero, as its constant coefficient is $1$.
\end{lemma}

\begin{theorem}[Degree additivity, \texttt{join\_natDegree}]
$\deg\big((P.\mathtt{join}\,Q).h\big) = \deg(P.h) + \deg(Q.h)$.
\end{theorem}

\begin{proof}[Proof sketch]
Over an integral domain $\deg(pq) = \deg p + \deg q$ for nonzero $p,q$; both factors are
nonzero by the previous lemma.
\end{proof}

\subsection{Algebraic structure}

\begin{proposition}[Point identity, \texttt{hstarPoint\_join}]
Let \texttt{hstarPoint} have $h = 1$. Then $(\mathtt{hstarPoint}.\mathtt{join}\,P).h = P.h$
since $1\cdot P.h = P.h$. Geometrically $\{pt\} * P$ is the pyramid over $P$.
\end{proposition}

\begin{proposition}[Commutativity, \texttt{join\_comm}]
$(P.\mathtt{join}\,Q).h = (Q.\mathtt{join}\,P).h$.
\end{proposition}

\begin{proposition}[Associativity, \texttt{join\_assoc}]
$((P.\mathtt{join}\,Q).\mathtt{join}\,R).h = (P.\mathtt{join}\,(Q.\mathtt{join}\,R)).h$.
\end{proposition}

\begin{corollary}[Monoid structure]
$(\mathtt{GorensteinHStar}, \mathtt{join}, \mathtt{hstarPoint})$ is a commutative monoid
(up to equality of underlying $\hstar$-polynomials).
\end{corollary}

\section{Worked examples}

\begin{example}[Point]
\texttt{hstarPoint}: $h = 1$, vector $(1)$; trivially Gorenstein.
\end{example}

\begin{example}[Reflexive polygon]
\texttt{hstarReflexivePolygon}: $h = 1 + 4z + z^2$, vector $(1,4,1)$; palindromic of
degree $2$, the $\hstar$-polynomial of a reflexive triangle of normalized volume $6$.
\end{example}

\begin{example}[Join of two reflexive polygons]
$(1+4z+z^2)^2 = 1 + 8z + 18z^2 + 8z^3 + z^4$, vector $(1,8,18,8,1)$; palindromic of
degree $4 = 2+2$, confirming Theorems~\ref{thm:closure} and the degree law.
\end{example}

\section{The genuine failure: free sums}

The intuition that combining Gorenstein polytopes can destroy symmetry is correct for the
\emph{free sum} $P \oplus Q$, whose $\hstar$-polynomial is \emph{not} the product of the
factors' but a more delicate convolution (Braun and collaborators). Reversal has no
compatibility with concatenation: concatenating palindromes $(1,4,1)$ and $(1,1)$ yields
$(1,4,1,1,1)$, not palindromic. Palindromy is preserved exactly by operations acting as a
graded ring multiplication; the join is such, the free sum is not.

\section{Algorithms}

\paragraph{Algorithm A --- \texttt{is\_gorenstein}.} Strip trailing zeros to find the true
degree $s$, then check $h_0 = 1$, all $h_i \ge 0$, and $h_i = h_{s-i}$. Cost $O(s)$.

\paragraph{Algorithm B --- \texttt{join\_hstar}.} Return the convolution
$(p*q)_i = \sum_{j+k=i} p_j q_k$. Cost $O(\deg p \cdot \deg q)$ (or $O(n\log n)$ via FFT).
By Theorem~\ref{thm:closure} the output is Gorenstein whenever both inputs are.

\section{Applications}

\begin{itemize}
\item \textbf{Toric geometry.} The join of Gorenstein Fano toric varieties retains the
canonical symmetry; the property now provably persists.
\item \textbf{Mirror symmetry.} Iterated joins yield a closed class of Gorenstein
polytopes with predictable degree bookkeeping.
\item \textbf{Construction.} The monoid structure assembles large Gorenstein examples from
join-prime blocks, with the point as neutral pyramiding.
\end{itemize}

\section{Future work}

\begin{conjecture}[Free-sum failure]
There exist reflexive $P, Q$ whose free sum $P \oplus Q$ is not Gorenstein. Testable:
formalize Braun's free-sum $\hstar$-identity and exhibit non-palindromic data.
\end{conjecture}
\begin{conjecture}[Index additivity]
Codegrees add under the join: $\deg \hstar_{P*Q} = \deg \hstar_P + \deg \hstar_Q$
(established as the degree-additivity theorem).
\end{conjecture}
\begin{conjecture}[Monoid / unique factorization]
$(\mathtt{GorensteinHStar}, \mathtt{join}, \mathtt{hstarPoint})$ is a free commutative
monoid on join-irreducible Gorenstein $\hstar$-polynomials.
\end{conjecture}
\begin{conjecture}[Symmetry-preserving operations]
Among product, sum, Hadamard product, and free-sum convolution, the palindromy-preserving
operations are precisely the graded ring multiplications.
\end{conjecture}
\begin{conjecture}[Effective Gorenstein from join roots]
If $p\cdot q$ is palindromic with $p,q$ having constant term $1$ and nonnegative
coefficients, then both are palindromic --- a converse to the join theorem.
\end{conjecture}

\section{Conclusion}

The join of two Gorenstein lattice polytopes is always Gorenstein: the join multiplies
$\hstar$-polynomials and products of palindromes are palindromes. The same algebra yields
degree additivity and a commutative-monoid structure with the point as identity. The
genuine locus of failure is the free sum.

