function JOIN_HSTAR(p, q):
    r <- array of zeros of length (len(p) + len(q) - 1)
    for j in 0 .. len(p)-1:
        for k in 0 .. len(q)-1:
            r[j + k] <- r[j + k] + p[j] * q[k]
    return r
